package com.lkaesberg.mensaapp

/**
 * Every dish photo in `mensa-food` (plates, per-category generics, sides) is
 * generated by the backend with an image model. China mainland's rules on
 * AI-generated content (CAC Interim Measures + Labeling Measures) and App
 * Store Connect's China compliance declarations only allow "No" when such
 * content is not offered there, so on the China App Store storefront the app
 * shows the plain placeholder tile instead of loading those images.
 */
object AiImagery {
    private val blockedStorefronts = setOf("CHN")

    fun isBlocked(storefront: String?): Boolean =
        storefront != null && storefront.uppercase() in blockedStorefronts

    /** Whether AI-generated dish photos may be shown on this device. */
    val allowed: Boolean get() = !isBlocked(appStoreCountry())
}

/**
 * The App Store country (ISO 3166-1 alpha-3) this install belongs to, or null
 * where there is none (Android: Google Play doesn't serve China mainland;
 * web).
 */
expect fun appStoreCountry(): String?
